"""Lay students out in rows of seats, ordered by last name."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check_inputs(students: List[Student], seats_per_row: int) -> None:
    if seats_per_row <= 0:
        raise ProjectError(f"seats per row must be positive: {seats_per_row}")
    if not students:
        raise ProjectError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower(), student.student_id)


def _row_line(number: int, members: List[Student]) -> str:
    names = " | ".join(member.display_name for member in members)
    return f"Row {number}: {names}"


# ---
def seat_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """Sort by last name and return one text line per row of seats."""
    _check_inputs(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    starts = range(0, len(ordered), seats_per_row)
    return [
        _row_line(number, ordered[begin:begin + seats_per_row])
        for number, begin in enumerate(starts, 1)
    ]

