import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make_student(ident, last, first):
    return Student(ident, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("3", "Halloway", "Juno"),
            make_student("1", "Dunmere", "Piet"),
            make_student("2", "Azura", "Kell")
        ]

    def test_sorted_and_split_into_rows(self):
        lines = seat_rows(self.students, 2)
        self.assertEqual(lines, [
            "Row 1: Azura, Kell | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_exceed_students(self):
        lines = seat_rows(self.students, 10)
        self.assertEqual(len(lines), 1)

    def test_first_name_breaks_ties(self):
        pair = [make_student("1", "Same", "Zed"), make_student("2", "Same", "Amy")]
        self.assertEqual(seat_rows(pair, 2), ["Row 1: Same, Amy | Same, Zed"])

    def test_bad_seat_counts_raise(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seat_rows(self.students, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
